from dataclasses import dataclass, field
from typing import Optional


@dataclass
class Product:
    sku: str
    name: str
    unit_cost: float
    reorder_point: int

    def to_dict(self) -> dict:
        return {
            "sku": self.sku,
            "name": self.name,
            "unit_cost": self.unit_cost,
            "reorder_point": self.reorder_point,
        }

    @classmethod
    def from_dict(cls, d: dict) -> "Product":
        return cls(
            sku=d["sku"],
            name=d["name"],
            unit_cost=float(d["unit_cost"]),
            reorder_point=int(d["reorder_point"]),
        )


@dataclass
class Location:
    code: str
    capacity: int

    def to_dict(self) -> dict:
        return {
            "code": self.code,
            "capacity": self.capacity,
        }

    @classmethod
    def from_dict(cls, d: dict) -> "Location":
        return cls(code=d["code"], capacity=int(d["capacity"]))


@dataclass
class StockLevel:
    sku: str
    location_code: str
    quantity: int

    def to_dict(self) -> dict:
        return {
            "sku": self.sku,
            "location_code": self.location_code,
