```python
"""Persistence layer: JSON file store with atomic writes."""
import json
import os
import tempfile

from models import Product, Location, StockLevel, Movement


class JsonStore:
    def __init__(self, path: str):
        self.path = path

    # ---------- raw on-disk object ----------

    def load(self) -> dict:
        """Load the raw JSON object, or return an empty skeleton if missing."""
        if not os.path.exists(self.path):
            return {"products": [], "locations": [], "stock": [], "movements": []}
        with open(self.path, "r", encoding="utf-8") as f:
            data = json.load(f)
        # Guarantee the four lists exist (fixture files may be minimal).
        data.setdefault("products", [])
        data.setdefault("locations", [])
        data.setdefault("stock", [])
        data.setdefault("movements", [])
        return data

    def save(self, data: dict) -> None:
        """Atomically write the raw JSON object (temp file + os.replace)."""
        payload = {
            "products": data.get("products", []),
            "locations": data.get("locations", []),
            "stock": data.get("stock", []),
            "movements": data.get("movements", []),
        }
        dir_name = os.path.dirname(os.path.abspath(self.path)) or "."
        os.makedirs(dir_name, exist_ok=True)
        fd, tmp_path = tempfile.mkstemp(prefix=".inventory-", dir=dir_name)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(payload, f, indent=2)
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp_path, self.path)
        except BaseException:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise

    # ---------- typed accessors ----------

    def get_product(self, sku: str) -> Product:
        for d in self.load()["products"]:
            if d.get("sku") == sku:
                return Product.from_dict(d)
        raise KeyError(f"unknown product sku: {sku!r}")

    def get_location(self, code: str) -> Location:
        for d in self.load()["locations"]:
            if d.get("code") == code:
                return Location.from_dict(d)
        raise KeyError(f"unknown location code: {code!r}")

    def stock_at(self, sku: str, code: str) -> int:
        for d in self.load()["stock"]:
            if d.get("sku") == sku and d.get("location_code") == code:
                return int(d.get("quantity", 0))
        return 0

    def set_stock(self, sku: str, code: str, qty: int) -> None:
        """Set quantity for (sku, code); creates or updates the row.
        Raises KeyError for unknown sku or location. Persists immediately."""
        # Validate references first (raises KeyError for unknown sku/location).
        self.get_product(sku)
        self.get_location(code)

        data = self.load()
        for row in data["stock"]:
            if row.get("sku") == sku and row.get("location_code") == code:
                row["quantity"] = int(qty)
                self.save(data)
                return
        data["stock"].append(StockLevel(sku, code, int(qty)).to_dict())
        self.save(data)

    def append_movement(self, m: Movement) -> None:
        data = self.load()
        data["movements"].append(m.to_dict())
        self.save(data)
