### rules.py
```python
"""Business rules for inventory movements."""
from models import Movement
from storage import JsonStore


class InsufficientStock(Exception):
    pass


class CapacityExceeded(Exception):
    pass


class DuplicateRef(Exception):
    pass


class Inventory:
    def __init__(self, store: JsonStore):
        self.store = store

    # ---------- helpers ----------

    def _check_ref_unique(self, ref: str) -> None:
        for d in self.store.load()["movements"]:
            if d.get("ref") == ref:
                raise DuplicateRef(f"duplicate ref: {ref!r}")

    def _location_used(self, code: str) -> int:
        """Total units currently stored at a location (all skus)."""
        return sum(
            int(d.get("quantity", 0))
            for d in self.store.load()["stock"]
            if d.get("location_code") == code
        )

    def _total_on_hand(self, sku: str) -> int:
        return sum(
            int(d.get("quantity", 0))
            for d in self.store.load()["stock"]
            if d.get("sku") == sku
        )

    def _record(self, kind: str, sku: str, qty: int, src, dst, ref: str) -> None:
        ts = Movement and _next_ts(self.store)
        m = Movement(kind=kind, sku=sku, qty=qty, src=src, dst=dst, ts=ts, ref=ref)
        self.store.append_movement(m)

    # ---------- operations ----------

    def receive(self, sku: str, qty: int, dst: str, ref: str) -> Movement:
        if qty <= 0:
            raise ValueError("qty must be > 0")
        self._check_ref_unique(ref)
        product = self.store.get_product(sku)   # KeyError if unknown sku
        location = self.store.get_location(dst)  # KeyError if unknown location

        incoming = self._location_used(dst) + qty
        if incoming > location.capacity:
            raise CapacityExceeded(
                f"location {dst!r} capacity {location.capacity} exceeded "
                f"(would hold {incoming})"
            )

        self.store.set_stock(sku, dst, self.store.stock_at(sku, dst) + qty)
        ts = _next_ts(self.store)
        m = Movement(kind="receive", sku=sku, qty=qty, src=None, dst=dst, ts=ts, ref=ref)
        self.store.append_movement(m)
        return m

    def ship(self, sku: str, qty: int, src: str, ref: str) -> Movement:
        if qty <= 0:
            raise ValueError("qty must be > 0")
        self._check_ref_unique(ref)
        self.store.get_product(sku)   # KeyError if unknown sku
        self.store.get_location(src)  # KeyError if unknown location

        on_hand = self.store.stock_at(sku, src)
        if qty > on_hand:
            raise InsufficientStock(
                f"insufficient stock for {sku!r} at {src!r}: "
                f"have {on_hand}, need {qty}"
            )

        self.store.set_stock(sku, src, on_hand - qty)
        ts = _next_ts(self.store)
        m = Movement(kind="ship", sku=sku, qty=qty, src=src, dst=None, ts=ts, ref=ref)
        self.store.append_movement(m)
        return m

    def transfer(self, sku: str, qty: int, src: str, dst: str, ref: str) -> Movement:
        if qty <= 0:
            raise ValueError("qty must be > 0")
        self._check_ref_unique(ref)
        self.store.get_product(sku)   # KeyError if unknown sku
        self.store.get_location(src)  # KeyError if unknown location
        self.store.get_location(dst)  # KeyError if unknown location

        on_hand = self.store.stock_at(sku, src)
        if qty > on_hand:
            raise InsufficientStock(
                f"insufficient stock for {sku!r} at {src!r}: "
                f"have {on_hand}, need {qty}"
            )
        if src == dst:
            # A transfer to the same location changes nothing but still logs
            # a movement; capacity cannot be exceeded since net usage is same.
            self._record_transfer(sku, qty, src, dst, ref)
            return self.store.load()["movements"][-1] and _last_movement(self.store)

        incoming = self._location_used(dst) + qty
        dst_loc = self.store.get_location(dst)
        if incoming > dst_loc.capacity:
            raise CapacityExceeded(
                f"location {dst!r} capacity {dst_loc.capacity} exceeded "
                f"(would hold {incoming})"
            )

        self.store.set_stock(sku, src, on_hand - qty)
        self.store.set_stock(sku, dst, self.store.stock_at(sku, dst) + qty)
        ts = _next_ts(self.store)
        m = Movement(kind="transfer", sku=sku, qty=qty, src=src, dst=dst, ts=ts, ref=ref)
        self.store.append_movement(m)
        return m

    def _record_transfer(self, sku: str, qty: int, src: str, dst: str, ref: str) -> None:
        ts = _next_ts(self.store)
        m = Movement(kind="transfer", sku=sku, qty=qty, src=src, dst=dst, ts=ts, ref=ref)
        self.store.append_movement(m)

    def adjust(self, sku: str, qty_delta: int, loc: str, ref: str) -> Movement:
        if qty_delta == 0:
            raise ValueError("qty_delta must be non-zero")
        self._check_ref_unique(ref)
        self.store.get_product(sku)   # KeyError if unknown sku
        self.store.get_location(loc)  # KeyError if unknown location

        current = self.store.stock_at(sku, loc)
        new_qty = current + qty_delta
        if new_qty < 0:
            raise InsufficientStock(
                f"adjust would take {sku!r} at {loc!r} below zero "
                f"(have {current}, delta {qty_delta})"
            )
        if qty_delta > 0:
            incoming = self._location_used(loc) + qty_delta
            capacity = self.store.get_location(loc).capacity
            if incoming > capacity:
                raise CapacityExceeded(
                    f"location {loc!r} capacity {capacity} exceeded "
                    f"(would hold {incoming})"
                )

        self.store.set_stock(sku, loc, new_qty)
        ts = _next_ts(self.store)
        m = Movement(kind="adjust", sku=sku, qty=qty_delta, src=loc, dst=None, ts=ts, ref=ref)
        self.store.append_movement(m)
        return m

    # ---------- reports ----------

    def total_on_hand(self, sku: str) -> int:
        return self._total_on_hand(sku)

    def below_reorder(self) -> list:
        skus = []
        for d in self.store.load()["products"]:
            sku = d["sku"]
            reorder = int(d.get("reorder_point", 0))
            if self._total_on_hand(sku) < reorder:
                skus.append(sku)
        return skus

    def valuation(self) -> float:
        data = self.store.load()
        cost_by_sku = {d["sku"]: float(d.get("unit_cost", 0.0)) for d in data["products"]}
        total = 0.0
        for row in data["stock"]:
            total += int(row.get("quantity", 0)) * cost_by_sku.get(row.get("sku"), 0.0)
        return total

    def ledger(self, sku: str) -> list:
        movements = [
            Movement.from_dict(d)
            for d in self.store.load()["movements"]
            if d.get("sku") == sku
        ]
        movements.sort(key=lambda m: m.ts)
        return movements


def _next_ts(store: JsonStore) -> int:
    """Timestamp for a new movement: max existing ts + 1 (starts at 1)."""
    ts_values = [int(d.get("ts", 0)) for d in store.load()["movements"]]
    return max(ts_values) + 1 if ts_values else 1


def _last_movement(store: JsonStore) -> Movement:
    return Movement.from_dict(store.load()["movements"][-1])
