"""Command-line interface for the warehouse inventory system."""
import argparse
import json
import sys

from rules import Inventory
from storage import JsonStore


def _build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(prog="inventory", description="Warehouse inventory CLI")
    p.add_argument("--db", required=True, help="path to the JSON store file")
    sub = p.add_subparsers(dest="command", required=True)

    p_recv = sub.add_parser("receive", help="receive stock into a location")
    p_recv.add_argument("sku")
    p_recv.add_argument("qty", type=int)
    p_recv.add_argument("dst")
    p_recv.add_argument("ref")

    p_ship = sub.add_parser("ship", help="ship stock out of a location")
    p_ship.add_argument("sku")
    p_ship.add_argument("qty", type=int)
    p_ship.add_argument("src")
    p_ship.add_argument("ref")

    p_xfer = sub.add_parser("transfer", help="transfer stock between locations")
    p_xfer.add_argument("sku")
    p_xfer.add_argument("qty", type=int)
    p_xfer.add_argument("src")
    p_xfer.add_argument("dst")
    p_xfer.add_argument("ref")

    p_adj = sub.add_parser("adjust", help="adjust stock by a delta (may be negative)")
    p_adj.add_argument("sku")
    p_adj.add_argument("qty_delta", type=int)
    p_adj.add_argument("loc")
    p_adj.add_argument("ref")

    p_rep = sub.add_parser("report", help="print inventory report")
    return p


def main(argv=None) -> int:
    parser = _build_parser()
    args = parser.parse_args(argv)

    store = JsonStore(args.db)
    inv = Inventory(store)

    try:
        if args.command == "receive":
            m = inv.receive(args.sku, args.qty, args.dst, args.ref)
            result = {"ok": True, "movement": m.to_dict()}
        elif args.command == "ship":
            m = inv.ship(args.sku, args.qty, args.src, args.ref)
            result = {"ok": True, "movement": m.to_dict()}
        elif args.command == "transfer":
            m = inv.transfer(args.sku, args.qty, args.src, args.dst, args.ref)
            result = {"ok": True, "movement": m.to_dict()}
        elif args.command == "adjust":
            m = inv.adjust(args.sku, args.qty_delta, args.loc, args.ref)
            result = {"ok": True, "movement": m.to_dict()}
        elif args.command == "report":
            total_units = sum(
                int(row.get("quantity", 0)) for row in store.load()["stock"]
            )
            result = {
                "valuation": inv.valuation(),
                "below_reorder": inv.below_reorder(),
                "total_units": total_units,
            }
        else:  # pragma: no cover - argparse enforces choices
            parser.error(f"unknown command: {args.command}")
    except Exception as e:  # ValueError, KeyError, InsufficientStock, etc.
        print(json.dumps({"ok": False, "error": str(e)}))
        return 1

    print(json.dumps(result))
    return 0


if __name__ == "__main__":
    sys.exit(main())
