"""Unit tests for the warehouse inventory system. Run: python -m unittest tests"""
import json
import os
import tempfile
import unittest

from models import Movement, Product
from rules import CapacityExceeded, DuplicateRef, InsufficientStock, Inventory
from storage import JsonStore


class BaseTestCase(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.db_path = os.path.join(self.tmp.name, "db.json")
        # Write the fixture file directly in the documented on-disk format.
        fixture = {
            "products": [
                {"sku": "CHAIR", "name": "Chair", "unit_cost": 25.0, "reorder_point": 10},
                {"sku": "TABLE", "name": "Table", "unit_cost": 100.0, "reorder_point": 5},
                {"sku": "LAMP", "name": "Lamp", "unit_cost": 12.5, "reorder_point": 20},
            ],
            "locations": [
                {"code": "A1", "capacity": 100},
                {"code": "B2", "capacity": 50},
                {"code": "C3", "capacity": 10},
            ],
            "stock": [
                {"sku": "CHAIR", "location_code": "A1", "quantity": 20},
                {"sku": "CHAIR", "location_code": "B2", "quantity": 5},
                {"sku": "TABLE", "location_code": "A1", "quantity": 8},
            ],
            "movements": [],
        }
        with open(self.db_path, "w", encoding="utf-8") as f:
            json.dump(fixture, f)
        self.store = JsonStore(self.db_path)
        self.inv = Inventory(self.store)

    def raw(self):
        with open(self.db_path, "r", encoding="utf-8") as f:
            return json.load(f)


class StorageTests(BaseTestCase):
    def test_load_returns_expected_lists(self):
        data = self.store.load()
        self.assertEqual(len(data["products"]), 3)
        self.assertEqual(len(data["locations"]), 3)
        self.assertEqual(len(data["stock"]), 3)
        self.assertEqual(data["movements"], [])

    def test_get_product_and_location(self):
        p = self.store.get_product("CHAIR")
        self.assertEqual(p.name, "Chair")
        self.assertEqual(p.unit_cost, 25.0)
        loc = self.store.get_location("A1")
        self.assertEqual(loc.capacity, 100)

    def test_get_unknown_raises_keyerror(self):
        with self.assertRaises(KeyError):
            self.store.get_product("NOPE")
        with self.assertRaises(KeyError):
            self.store.get_location("ZZ9")

    def test_stock_at_defaults_to_zero(self):
        self.assertEqual(self.store.stock_at("LAMP", "A1"), 0)

    def test_set_stock_updates_and_creates(self):
        self.store.set_stock("CHAIR", "A1", 15)
        self.assertEqual(self.store.stock_at("CHAIR", "A1"), 15)
        self.store.set_stock("LAMP", "C3", 7)
        self.assertEqual(self.store.stock_at("LAMP", "C3"), 7)
        rows = [r for r in self.raw()["stock"] if r["sku"] == "LAMP"]
        self.assertEqual(len(rows), 1)

    def test_set_stock_unknown_refs_raise(self):
        with self.assertRaises(KeyError):
            self.store.set_stock("GHOST", "A1", 1)
        with self.assertRaises(KeyError):
            self.store.set_stock("CHAIR", "NOWHERE", 1)

    def test_append_movement_persists(self):
        m = Movement("receive", "CHAIR", 3, None, "A1", 1, "R-1")
        self.store.append_movement(m)
        raw = self.raw()
        self.assertEqual(len(raw["movements"]), 1)
        self.assertEqual(raw["movements"][0]["ref"], "R-1")

    def test_atomic_save_leaves_no_temp_files(self):
        self.store.set_stock("CHAIR", "A1", 11)
        leftovers = [
            n for n in os.listdir(self.tmp.name)
            if n.startswith(".inventory-")
        ]
        self.assertEqual(leftovers, [])


class RuleTests(BaseTestCase):
    # --- quantity validation ---

    def test_receive_zero_or_negative_qty_raises(self):
        with self.assertRaises(ValueError):
            self.inv.receive("CHAIR", 0, "A1", "R-Z")
        with self.assertRaises(ValueError):
            self.inv.receive("CHAIR", -5, "A1", "R-N")

    def test_ship_zero_or_negative_qty_raises(self):
        with self.assertRaises(ValueError):
            self.inv.ship("CHAIR", 0, "A1", "S-Z")
        with self.assertRaises(ValueError):
            self.inv.ship("CHAIR", -1, "A1", "S-N")

    def test_transfer_zero_or_negative_qty_raises(self):
        with self.assertRaises(ValueError):
            self.inv.transfer("CHAIR", 0, "A1", "B2", "T-Z")
        with self.assertRaises(ValueError):
            self.inv.transfer("CHAIR", -2, "A1", "B2", "T-N")

    def test_adjust_zero_delta_raises(self):
        with self.assertRaises(ValueError):
            self.inv.adjust("CHAIR", 0, "A1", "AD-Z")

    # --- insufficient stock ---

    def test_ship_more_than_on_hand_raises(self):
        with self.assertRaises(InsufficientStock):
            self.inv.ship("CHAIR", 21, "A1", "S-1")  # only 20 at A1

    def test_transfer_more_than_on_hand_raises(self):
        with self.assertRaises(InsufficientStock):
            self.inv.transfer("CHAIR", 6, "B2", "A1", "T-1")  # only 5 at B2

    def test_failed_ship_persists_nothing(self):
        with self.assertRaises(InsufficientStock):
            self.inv.ship("CHAIR", 999, "A1", "S-X")
        self.assertEqual(self.store.stock_at("CHAIR", "A1"), 20)
        self.assertEqual(self.raw()["movements"], [])

    # --- capacity ---

    def test_receive_exceeding_capacity_raises(self):
        # C3 capacity 10, currently 0; receiving 11 exceeds it.
        with self.assertRaises(CapacityExceeded):
            self.inv.receive("LAMP", 11, "C3", "R-CAP")

    def test_capacity_counts_all_skus_at_location(self):
        # A1 holds 20 CHAIR + 8 TABLE = 28; capacity 100; 73 more fits exactly.
        self.inv.receive("LAMP", 73, "A1", "R-FIT")
        self.assertEqual(self.store.stock_at("LAMP", "A1"), 73)
        # One more unit would exceed capacity.
        with self.assertRaises(CapacityExceeded):
            self.inv.receive("LAMP", 1, "A1", "R-OVER")

    def test_transfer_exceeding_dst_capacity_raises(self):
        # B2 holds 5 CHAIRs, capacity 50; moving 46 CHAIRs from A1 -> B2
        # would put B2 at 51 > 50.
        with self.assertRaises(CapacityExceeded):
            self.inv.transfer("CHAIR", 46, "A1", "B2", "T-CAP")

    # --- duplicate ref ---

    def test_duplicate_ref_raises_and_changes_nothing(self):
        self.inv.receive("LAMP", 5, "C3", "R-DUP")
        before = self.raw()
        with self.assertRaises(DuplicateRef):
            self.inv.receive("LAMP", 5, "C3", "R-DUP")
        with self.assertRaises(DuplicateRef):
            self.inv.ship("CHAIR", 1, "A1", "R-DUP")
        self.assertEqual(self.raw(), before)

    # --- happy paths ---

    def test_receive_updates_stock_and_logs_movement(self):
        m = self.inv.receive("LAMP", 4, "C3", "R-OK")
        self.assertEqual(self.store.stock_at("LAMP", "C3"), 4)
        self.assertEqual(m.kind, "receive")
        self.assertEqual(m.dst, "C3")
        self.assertEqual(len(self.raw()["movements"]), 1)

    def test_ship_updates_stock_and_logs_movement(self):
        self.inv.ship("CHAIR", 6, "A1", "S-OK")
        self.assertEqual(self.store.stock_at("CHAIR", "A1"), 14)

    def test_transfer_moves_stock_between_locations(self):
        self.inv.transfer("CHAIR", 5, "A1", "B2", "T-OK")
        self.assertEqual(self.store.stock_at("CHAIR", "A1"), 15)
        self.assertEqual(self.store.stock_at("CHAIR", "B2"), 10)

    def test_adjust_positive_and_negative(self):
        self.inv.adjust("CHAIR", 3, "A1", "AD-P")
        self.assertEqual(self.store.stock_at("CHAIR", "A1"), 23)
